            assertThat(response.status()).isEqualTo(IngestStatus.ACCEPTED);
        }
    }

    @Test
    void windowBoundaryEvidenceUsesClosestMessage() {
        // CAMERA 窗口 60ms：恰好 -60ms 闭区间命中
        ingest(SensorType.CAMERA, "c-edge", T - 60 * MS);
