// Windows 下 JDK 启动器按 ANSI 代码页解码测试 worker 的 @argfile，项目路径含非 ASCII 字符时
// classpath 会失效（ClassNotFoundException: GradleWorkerMain）。仅在此场景把构建输出重定向到
// ASCII 临时目录，使 worker classpath 全部可解码；ASCII 路径环境保持标准 build/ 布局不变。
if (System.getProperty('os.name', '').toLowerCase().contains('win')) {
    def projectPath = layout.projectDirectory.asFile.absolutePath
    if (!java.nio.charset.StandardCharsets.US_ASCII.newEncoder().canEncode(projectPath)) {
        def asciiBuildRoot = new File(System.getProperty('java.io.tmpdir'),
                'sensor-sync-gradle-build/020-a')
        layout.buildDirectory.set(new File(asciiBuildRoot, 'build'))
        logger.lifecycle("项目路径含非 ASCII 字符，构建输出重定向至: {}", layout.buildDirectory.get().asFile)
    }
}

