tasks.named('test') {
    useJUnitPlatform()
    // Windows JDK 启动器按系统 ANSI 代码页（本机 GBK）解码 @argfile，而 Gradle 以 UTF-8 写入；
    // 当 GRADLE_USER_HOME/项目路径含非 ASCII 字符时 worker classpath 失效。
    // 用 ASCII 临时目录中的包装器启动 java：先把 argfile 从 UTF-8 转码为 GBK 再透传全部参数。
    if (System.getProperty('os.name', '').toLowerCase().contains('win')) {
        def projectPath = layout.projectDirectory.asFile.absolutePath
        if (!java.nio.charset.StandardCharsets.US_ASCII.newEncoder().canEncode(projectPath)) {
            def launcher = javaToolchains.launcherFor {
                languageVersion = JavaLanguageVersion.of(21)
            }.get()
            def realJava = launcher.executablePath.asFile.absolutePath
            def toolDir = new File(System.getProperty('java.io.tmpdir'),
                    'sensor-sync-gradle-build/020-a/tool')
            toolDir.mkdirs()

            def ps1 = new File(toolDir, 'java-argfile-cp936.ps1')
            ps1.text = '''$ErrorActionPreference = 'Stop'
param(
  [Parameter(ValueFromRemainingArguments = $true)][string[]]$JArgs
)
$final = New-Object 'System.Collections.Generic.List[string]'
foreach ($a in $JArgs) {
  if ($a.StartsWith('@')) {
    $src = $a.Substring(1).Trim('"')
    $text = [System.IO.File]::ReadAllText($src, (New-Object System.Text.UTF8Encoding($false)))
    $dst = [System.IO.Path]::Combine([System.IO.Path]::GetDirectoryName($src),
        [System.IO.Path]::GetFileNameWithoutExtension($src) + '.cp936.txt')
    [System.IO.File]::WriteAllText($dst, $text, [System.Text.Encoding]::GetEncoding(936))
    $final.Add('@' + $dst)
  } else {
    $final.Add($a)
  }
}
& $env:GRADLE_REAL_JAVA @final
exit $LASTEXITCODE
'''

            def bat = new File(toolDir, 'java-argfile-cp936.bat')
            bat.text = '@echo off\r\npowershell -NoProfile -ExecutionPolicy Bypass -File "' +
                    ps1.absolutePath + '" %*\r\n'

            environment 'GRADLE_REAL_JAVA', realJava
            executable = bat.absolutePath
        }
    }
    testLogging {
        events 'passed', 'skipped', 'failed'
    }
}

