// （GRADLE_USER_HOME 已由 gradlew 经目录联接映射为 ASCII），测试完成后把报告复制回项目内。
// ASCII 路径环境保持标准 build/ 布局，不受影响。
def asciiBuildDir = null
if (System.getProperty('os.name', '').toLowerCase().contains('win')) {
    def projectPath = layout.projectDirectory.asFile.absolutePath
    if (!java.nio.charset.StandardCharsets.US_ASCII.newEncoder().canEncode(projectPath)) {
        asciiBuildDir = new File(System.getProperty('java.io.tmpdir'),
                'sensor-sync-gradle/020-a/build')
        layout.buildDirectory.set(asciiBuildDir)
        logger.lifecycle('项目路径含非 ASCII 字符，构建输出重定向至: {}', asciiBuildDir)
    }
}

