    useJUnitPlatform()
    testLogging {
        events 'passed', 'skipped', 'failed'
    }
    if (asciiBuildDir != null) {
        // 测试结束后把标准报告复制回项目 build/ 目录，便于归档与核验
        doLast {
            def backTo = layout.projectDirectory.dir('build')
            copy {
                from(new File(asciiBuildDir, 'reports/tests/test'))
                into(new File(backTo.asFile, 'reports/tests/test'))
            }
            copy {
                from(new File(asciiBuildDir, 'test-results/test'))
                into(new File(backTo.asFile, 'test-results/test'))
            }
        }
    }
}

