)
$ErrorActionPreference = 'Stop'
$final = New-Object 'System.Collections.Generic.List[string]'
foreach ($a in $JArgs) {
  if ($a.StartsWith('@')) {
    $src = $a.Substring(1).Trim('"')
    $text = [System.IO.File]::ReadAllText($src, (New-Object System.Text.UTF8Encoding($false)))
    $dst = [System.IO.Path]::Combine([System.IO.Path]::GetDirectoryName($src),
        [System.IO.Path]::GetFileNameWithoutExtension($src) + '.cp936.txt')
